lumnName\":\"Master Min Stock\",\"isUserCalculation\":false},{\"prepColumnName\":\"Master Max Stock\",\"isUserCalculation\":false},{\"prepColumnName\":\"Master Pres Stock\",\"isUserCalculation\":false},{\"prepColumnName\":\"Master Sync Status\",\"isUserCalculation\":false},{\"prepColumnName\":\"Supp Pack Size\",\"isUserCalculation\":false},{\"prepColumnName\":\"Inner Pack Size\",\"isUserCalculation\":false},{\"prepColumnName\":\"Supplier Unit Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Pallet Tier\",\"isUserCalculation\":false},{\"prepColumnName\":\"Pallet High\",\"isUserCalculation\":false},{\"prepColumnName\":\"Pallet Order Multiple\",\"isUserCalculation\":false},{\"prepColumnName\":\"Current Soh\",\"isUserCalculation\":false},{\"prepColumnName\":\"Weighted Avg Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Unit Retail\",\"isUserCalculation\":false},{\"prepColumnName\":\"Soh Cost Value\",\"isUserCalculation\":false},{\"prepColumnName\":\"Stock Position\",\"isUserCalculation\":false},{\"prepColumnName\":\"Implied Roq\",\"isUserCalculation\":false},{\"prepColumnName\":\"Last Repl Attr Update\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Dept No\"],\"expressionSourceColumns\":[\"Dept No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Dept No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Dept No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Class No\"],\"expressionSourceColumns\":[\"Class No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Class No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Class No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Subclass No\"],\"expressionSourceColumns\":[\"Subclass No\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Subclass No\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass No\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT\\n    TRUNC(SYSDATE)                                  AS \\\"Report Date\\\",\\n    im.DEPT                                         AS \\\"Dept No\\\",\\n    d.DEPT_NAME                                     AS \\\"Dept Name\\\",\\n    im.CLASS                                        AS \\\"Class No\\\",\\n    c.CLASS_NAME                                    AS \\\"Class Name\\\",\\n    im.SUBCLASS                                     AS \\\"Subclass No\\\",\\n    sc.SUB_NAME                                     AS \\\"Subclass Name\\\",\\n    im.ITEM                                         AS \\\"Item ID\\\",\\n    im.ITEM_DESC                                    AS \\\"Item Description\\\",\\n    im.STANDARD_UOM                                 AS \\\"UOM\\\",\\n    im.PACK_IND                                     AS \\\"Pack IND\\\",\\n    im.STATUS                                       AS \\\"Item Status\\\",\\n    ril.LOCATION                                    AS \\\"Location ID\\\",\\n    il.LOC_TYPE                                     AS \\\"LOC Type\\\",\\n    CASE il.LOC_TYPE\\n            WHEN 'S'\\n                THEN 'Store'\\n            WHEN 'W'\\n                THEN 'Warehouse'\\n    END                                                 AS \\\"LOC Type DESC\\\",\\n\\n    CASE il.LOC_TYPE\\n            WHEN 'S'\\n                THEN st.STORE_NAME\\n            WHEN 'W'\\n                THEN wh.WH_NAME\\n    END                                                 AS location_name,\\n\\n    il.STATUS                                       AS \\\"Item LOC Status\\\",\\n    CASE il.STATUS\\n            WHEN 'A'\\n                THEN 'Active'\\n            WHEN 'C'\\n                THEN 'Discontinued'\\n            WHEN 'I'\\n                THEN 'Inactive'\\n            WHEN 'D'\\n                THEN 'Delete'\\n    END                                                 AS \\\"Item LOC Status DESC\\\",\\n\\n    ril.REPL_METHOD                                 AS \\\"Repl Method\\\",\\n    CASE ril.REPL_METHOD\\n            WHEN 'C'\\n                THEN 'Constant'\\n            WHEN 'D'\\n                THEN 'Dynamic'\\n            WHEN 'DI'\\n                THEN 'Dynamic - Issues'\\n            WHEN 'S'\\n                THEN 'Dynamic - Seasonal'\\n            WHEN 'F'\\n                THEN 'Floating Point'\\n            WHEN 'M'\\n                THEN 'Min/Max'\\n            WHEN 'SO'\\n                THEN 'Store Orders'\\n            WHEN 'T'\\n                THEN 'Time Supply'\\n            WHEN 'TI'\\n                THEN 'Time Supply - Issues'\\n            WHEN 'E'\\n                THEN 'Time Supply - Seasonal'\\n            ELSE ril.REPL_METHOD\\n    END                                                 AS \\\"Repl Method DESC\\\",\\n\\n    ril.STOCK_CAT                                   AS \\\"Stock Category\\\",\\n    CASE ril.STOCK_CAT\\n            WHEN 'C'\\n                THEN 'Cross-Docked'\\n            WHEN 'D'\\n                THEN 'Direct to Store'\\n            WHEN 'L'\\n                THEN 'WH/Cross Link'\\n            WHEN 'W'\\n                THEN 'Warehouse Stocked'\\n            WHEN 'X'\\n                THEN 'PO Cross-link'\\n            ELSE ril.STOCK_CAT\\n    END                                                 AS \\\"Stock Category DESC\\\",\\n\\n    ril.REPL_ORDER_CTRL                             AS \\\"Order Control\\\",\\n    CASE ril.REPL_ORDER_CTRL\\n            WHEN 'A'\\n                THEN 'Automatic'\\n            WHEN 'B'\\n                THEN 'Buyer Worksheet'\\n            WHEN 'M'\\n                THEN 'Manual'\\n            WHEN 'S'\\n                THEN 'Semi-Automatic'\\n            ELSE ril.REPL_ORDER_CTRL\\n    END                                                 AS \\\"Order Control DESC\\\",\\n\\n    ril.MIN_STOCK                                   AS \\\"Min Stock\\\",\\n    ril.MAX_STOCK                                   AS \\\"Max Stock\\\",\\n    ril.MIN_STOCK                                   AS \\\"Reorder Point\\\",\\n    NVL(ril.MAX_STOCK, 0) - NVL(ril.MIN_STOCK, 0)   AS \\\"Repl Band\\\",\\n    mra.PRES_STOCK                                  AS \\\"Presentation Stock\\\",\\n    ril.DEMO_STOCK                                  AS \\\"Demo Stock\\\",\\n    GREATEST(NVL(ils.STOCK_ON_HAND, 0) - NVL(mra.PRES_STOCK, 0) - NVL(ril.DEMO_STOCK, 0), 0)AS \\\"Net Available For Repl\\\",\\n    ril.SOURCE_WH                                   AS \\\"Source WH ID\\\",\\n    swh.WH_NAME                                     AS \\\"Source WH Name\\\",\\n    ril.PRIMARY_REPL_SUPPLIER                       AS \\\"Supplier ID\\\",\\n    sp.SUP_NAME                                     AS \\\"Supplier Name\\\",\\n    sp.SUP_STATUS                                   AS \\\"Supplier Status\\\",\\n    isc.ORIGIN_COUNTRY_ID                           AS \\\"Origin Country\\\",\\n    ril.WH_LEAD_TIME                                AS \\\"WH To Store Lead Time\\\",\\n    isc.LEAD_TIME                                   AS \\\"Supp Lead Time\\\",\\n    iscl.PICKUP_LEAD_TIME                           AS \\\"LOC Pickup Lt Override\\\",\\n    NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME)AS \\\"Effective Pickup Lt\\\",\\n    NVL(ril.SUPP_LEAD_TIME, isc.LEAD_TIME)          AS \\\"Effective Supp Lead Time\\\",\\n    ril.ADJ_SUPP_LEAD_TIME                          AS \\\"Adj Supp Lead Time\\\",\\n    ril.ADJ_PICKUP_LEAD_TIME                        AS \\\"Adj Pickup Lead Time\\\",\\n    NVL(NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME), 0) + NVL(ril.WH_LEAD_TIME, 0)AS \\\"Total Pipeline Days\\\",\\n    ril.REVIEW_CYCLE                                AS \\\"Review Cycle\\\",\\n    CASE ril.REVIEW_CYCLE\\n            WHEN '0'\\n                THEN 'Every Week'\\n            WHEN '1'\\n                THEN 'Every Day'\\n            WHEN '2'\\n                THEN 'Every 2 Weeks'\\n            WHEN '3'\\n                THEN 'Every 3 Weeks'\\n            WHEN '4'\\n                THEN 'Every 4 Weeks'\\n            WHEN '5'\\n                THEN 'Every 5 Weeks'\\n            WHEN '6'\\n                THEN 'Every 6 Weeks'\\n            WHEN '7'\\n                THEN 'Every 7 Weeks'\\n            WHEN '8'\\n                THEN 'Every 8 Weeks'\\n            WHEN '9'\\n                THEN 'Every 9 Weeks'\\n            WHEN '10'\\n                THEN 'Every 10 Weeks'\\n            WHEN '11'\\n                THEN 'Every 11 Weeks'\\n            WHEN '12'\\n                THEN 'Every 12 Weeks'\\n            WHEN '13'\\n                THEN 'Every 13 Weeks'\\n            WHEN '14'\\n                THEN 'Every 14 Weeks'\\n            ELSE 'Every ' || ril.REVIEW_CYCLE || ' Weeks'\\n    END                                                 AS \\\"Review Cycle DESC\\\",\\n\\n    NVL(rd_pivot.MON, 'N')                          AS \\\"Review Mon\\\",\\n    NVL(rd_pivot.TUE, 'N')                          AS \\\"Review Tue\\\",\\n    NVL(rd_pivot.WED, 'N')                          AS \\\"Review Wed\\\",\\n    NVL(rd_pivot.THU, 'N')                          AS \\\"Review Thu\\\",\\n    NVL(rd_pivot.FRI, 'N')                          AS \\\"Review Fri\\\",\\n    NVL(rd_pivot.SAT, 'N')                          AS \\\"Review Sat\\\",\\n    NVL(rd_pivot.SUN, 'N')                          AS \\\"Review Sun\\\",\\n    ril.NON_SCALING_IND                             AS \\\"Scaling Exempt IND\\\",\\n    CASE ril.NON_SCALING_IND\\n            WHEN 'Y'\\n                THEN 'Scaling Exempt'\\n            WHEN 'N'\\n                THEN 'Subject to Scaling'\\n            ELSE 'Not Set'\\n    END                                                 AS \\\"Scaling Exempt DESC\\\",\\n\\n    ril.MAX_SCALE_VALUE                             AS \\\"Max Scale Amount\\\",\\n    ril.PRIMARY_PACK_NO                             AS \\\"Primary Repl Pack\\\",\\n    prim_pack.ITEM_DESC                             AS \\\"Primary Repl Pack DESC\\\",\\n    mra.MIN_STOCK                                   AS \\\"Master Min Stock\\\",\\n    mra.MAX_STOCK                                   AS \\\"Master Max Stock\\\",\\n    mra.PRES_STOCK                                  AS \\\"Master Pres Stock\\\",\\n    CASE WHEN mra.ITEM IS NOT NULL AND (NVL(ril.MIN_STOCK,-9) != NVL(mra.MIN_STOCK,-9) OR NVL(ril.MAX_STOCK,-9) != NVL(mra.MAX_STOCK,-9)) THEN 'DIVERGED FROM MASTER'\\n            WHEN mra.ITEM IS NULL\\n                THEN 'NO MASTER RECORD'\\n            ELSE 'IN SYNC WITH MASTER'\\n    END                                                 AS \\\"Master Sync Status\\\",\\n\\n    isc.SUPP_PACK_SIZE                              AS \\\"Supp Pack Size\\\",\\n    isc.INNER_PACK_SIZE                             AS \\\"Inner Pack Size\\\",\\n    isc.UNIT_COST                                   AS \\\"Supplier Unit Cost\\\",\\n    isc.TI                                          AS \\\"Pallet Tier\\\",\\n    isc.HI                                          AS \\\"Pallet High\\\",\\n    NVL(isc.TI, 0) * NVL(isc.HI, 0) * NVL(isc.SUPP_PACK_SIZE, 1)AS \\\"Pallet Order Multiple\\\",\\n    ils.STOCK_ON_HAND                               AS \\\"Current Soh\\\",\\n    ils.AV_COST                                     AS \\\"Weighted Avg Cost\\\",\\n    il.SELLING_UNIT_RETAIL                          AS \\\"Unit Retail\\\",\\n    ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2)AS \\\"Soh Cost Value\\\",\\n    CASE WHEN NVL(ils.STOCK_ON_HAND, 0) = 0 THEN 'OUT OF STOCK'\\n            WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; NVL(ril.MIN_STOCK, 0)\\n                THEN 'BELOW MIN - REORDER REQUIRED'\\n            WHEN NVL(ils.STOCK_ON_HAND, 0) BETWEEN NVL(ril.MIN_STOCK, 0) AND NVL(ril.MAX_STOCK, 0)\\n                THEN 'WITHIN RANGE'\\n            WHEN NVL(ils.STOCK_ON_HAND, 0) &gt; NVL(ril.MAX_STOCK, 0)\\n                THEN 'ABOVE MAX - OVERSTOCK'\\n            ELSE 'UNKNOWN'\\n    END                                                 AS \\\"Stock Position\\\",\\n\\n    GREATEST(NVL(ril.MAX_STOCK, 0) - NVL(ils.STOCK_ON_HAND, 0), 0)AS \\\"Implied Roq\\\",\\n    ril.LAST_UPDATE_DATETIME                        AS \\\"Last Repl Attr Update\\\"\\n\\nFROM\\n    MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril\\n\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM                   = il.ITEM\\n                                                     AND  ril.LOCATION               = il.LOC\\n                                                     AND  ril.LOC_TYPE               = il.LOC_TYPE\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM                   = im.ITEM\\n                                                     AND  im.TRAN_LEVEL              = im.ITEM_LEVEL\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT                    = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT                    = c.DEPT\\n                                                     AND  im.CLASS                   = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT                    = sc.DEPT\\n                                                     AND  im.CLASS                   = sc.CLASS\\n                                                     AND  im.SUBCLASS                = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION               = st.STORE\\n                                                     AND  il.LOC_TYPE                = 'S'\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION               = wh.WH\\n                                                     AND  il.LOC_TYPE                = 'W'\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH             swh     ON  ril.SOURCE_WH              = swh.WH\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM                   = ils.ITEM\\n                                                     AND  ril.LOCATION               = ils.LOC\\n                                                     AND  ils.LOC_TYPE               = ril.LOC_TYPE\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM                   = isc.ITEM\\n                                                     AND  ril.PRIMARY_REPL_SUPPLIER  = isc.SUPPLIER\\n                                                     AND  isc.PRIMARY_SUPP_IND       = 'Y'\\n                                                     AND  isc.PRIMARY_COUNTRY_IND    = 'Y'\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl\\n                                                      ON  ril.ITEM                   = iscl.ITEM\\n                                                     AND  ril.PRIMARY_REPL_SUPPLIER  = iscl.SUPPLIER\\n                                                     AND  iscl.LOC                   = ril.LOCATION\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER  = sp.SUPPLIER\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_MASTER_REPL_ATTR mra   ON  ril.ITEM                   = mra.ITEM\\n                                                     AND  ril.LOCATION               = mra.LOCATION\\n\\n    LEFT JOIN (\\n

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT\\n            ITEM,\\n            LOCATION,\\n            MAX(CASE WHEN WEEKDAY = 1 THEN 'Y' ELSE 'N' END) AS MON,\\n            MAX(CASE WHEN WEEKDAY = 2 THEN 'Y' ELSE 'N' END) AS TUE,\\n            MAX(CASE WHEN WEEKDAY = 3 THEN 'Y' ELSE 'N' END) AS WED,\\n            MAX(CASE WHEN WEEKDAY = 4 THEN 'Y' ELSE 'N' END) AS THU,\\n            MAX(CASE WHEN WEEKDAY = 5 THEN 'Y' ELSE 'N' END) AS FRI,\\n            MAX(CASE WHEN WEEKDAY = 6 THEN 'Y' ELSE 'N' END) AS SAT,\\n            MAX(CASE WHEN WEEKDAY = 7 THEN 'Y' ELSE 'N' END) AS SUN\\n        FROM  MFCS_RDS.RDS_WV_REPL_DAY\\n        GROUP BY ITEM, LOCATION\\n    ) rd_pivot                                            ON  ril.ITEM               = rd_pivot.ITEM\\n                                                         AND  ril.LOCATION           = rd_pivot.LOCATION\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_MASTER     prim_pack\\n                                                          ON  ril.PRIMARY_PACK_NO    = prim_pack.ITEM\\n\\nWHERE\\n    ril.REPL_METHOD  IS NOT NULL\\n    AND il.STATUS    IN ('A','C')\\n    AND im.STATUS     = 'A'\\n\\nORDER BY\\n    d.DEPT_NAME,\\n    c.CLASS_NAME,\\n    sc.SUB_NAME,\\n    im.ITEM_DESC,\\n    il.LOC_TYPE,\\n    CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-14T16:34:32.475+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_542_Repl_Param_Full_Detail'","parent-namespace":"ReCommon","parent-name":"RPT_542_Repl_Param_Full_Detail","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_542_Repl_Param_Full_Detail'"}
